t-xl font-bold">Rincian biaya</h2><div class="space-y-4 mt-5">@foreach($order->items as $item)<div class="flex justify-between gap-4 text-sm"><span>{{ $item->item_name }} × {{ $item->quantity }}</span><b>Rp{{ number_format($item->line_total,0,',','.') }}</b></div>@endforeach</div><hr class="border-slate-700 my-5"><div class="flex justify-between text-sm muted"><span>Subtotal</span><span>Rp{{ number_format($order->subtotal,0,',','.') }}</span></div><div class="flex justify-between text-sm muted mt-2"><span>Biaya kunjungan</span><span>Rp{{ number_format($order->visit_fee,0,',','.') }}</span></div><div class="flex justify-between text-xl font-black mt-5"><span>Total</span><span class="text-orange-400">Rp{{ number_format($order->total,0,',','.') }}</span></div><p class="muted text-sm mt-5">Pembayaran: <b class="text-white">{{ $order->payment?->status ?? 'pending' }}</b></p>@if($order->payment?->snap_token)<button id="pay" class="btn w-full mt-5">Bayar dengan Midtrans</button>@elseif($order->payment_method==='midtrans' && $order->payment?->status!=='paid')<p class="text-amber-300 text-sm mt-4">Token pembayaran belum tersedia. Periksa konfigurasi Midtrans Sandbox.</p><form method="POST" action="{{ route('orders.payment.retry',$order) }}" class="mt-3">@csrf<button class="btn w-full">Coba buat token pembayaran</button></form>@endif</div></div></section>@endsection
