@push('scripts')<script>
const orderUrl=@json(route('orders.tracking',$order));const target=[{{ $order->latitude ?? -6.2 }},{{ $order->longitude ?? 106.816666 }}];let map=L.map('trackmap').setView(target,{{ $order->latitude ? 14 : 5 }});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);let customerMarker=null,mechanicMarker=null;if({{ $order->latitude!==null && $order->longitude!==null?'true':'false' }})customerMarker=L.marker(target).addTo(map).bindPopup('Lokasi pelanggan');async function refreshTrack(){try{const r=await fetch(orderUrl,{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();document.getElementById('track-status').textContent='Status: '+d.status.replaceAll('_',' ')+(d.mechanic?.recorded_at?' · GPS terakhir '+d.mechanic.recorded_at:' · Menunggu GPS mekanik');if(d.mechanic){const p=[Number(d.mechanic.latitude),Number(d.mechanic.longitude)];if(mechanicMarker)mechanicMarker.setLatLng(p);else mechanicMarker=L.marker(p).addTo(map).bindPopup('Lokasi mekanik');if(!customerMarker)map.setView(p,14);}}catch(e){document.getElementById('track-status').textContent='Gagal memperbarui pelacakan. Periksa koneksi.';}}refreshTrack();setInterval(refreshTrack,15000);@if($order->payment?->snap_token)document.getElementById('pay')?.addEventListener('click',()=>snap.pay(@json($order->payment->snap_token)));@endif
</script>@endpush
